// Session-based training replaces calendar-driven navigation.
const additions=[
 ['widechoice','Beat them outside—or combine','Attacking','feint','Make the defender choose.','A winger can dribble, combine or keep possession. The defender’s stance helps you choose.','Approach under control, look at the defender, then commit.','Dribbling into a closed lane just because you planned a move.','Set two gates beyond a cone. Approach slowly, feint, and exit through either gate with a controlled touch.','Your brother blocks one gate at walking speed. Take the open gate or pass back; swap after five attempts.','Add light live pressure once both players can stop safely.','The defender blocks the touchline and a teammate is free inside. Must you force the outside dribble?','No. Combine inside or keep the ball until a better opening appears.','Notice one time you changed your choice because of the defender.'],
 ['overlap','Overlap at the right moment','Attacking','wide','Run when it helps the ball carrier.','An outside run can create a pass or draw a defender away. It is useful when the ball carrier has time to use it.','Check the ball carrier, then run beyond on the outside.','Running past while the teammate needs a close supporting pass.','Mark a wide player with a cone. Walk from behind to an outside lane; pause and imagine the passing window.','One dribbles slowly inward while the other overlaps. Pass only when the lane is clear. Swap.','With a third player, add a passive defender to choose pass or keep.','Your teammate is trapped and facing backward. Is sprinting past always helpful?','A closer support angle may help first. Time the run to their ability to play.','Find an overlap that created space even without receiving.'],
 ['underlap','Find the inside running lane','Attacking','behind','The useful space may be inside.','An inside run can connect a wide player to central space when the defender is drawn outward.','Check central traffic before moving inside the wide teammate.','Running into the same space as another attacker.','Place a wide cone and a central gate. Walk a curved run through the gate, checking an imaginary passer.','Your brother holds the ball wide. Run inside only after eye contact and an open lane; receive gently.','Add a passive defender blocking either the inside or return option.','Another teammate is already arriving in the inside lane. Should you run there too?','Hold width or support behind instead; avoid crowding their space.','Notice whether your movement opened or crowded a passing lane.'],
 ['strikercheck','Come short, then go behind','Attacking','behind','Move the defender before your run.','A striker can change distance and direction to find separation, while staying available to the passer.','Check toward the ball, then change direction when the passer can play.','Going behind before the passer has a chance to look up.','Use a cone as a defender. Walk toward a serving point, pause, then curve into space behind.','Your brother signals when ready to pass. Check short, then time a curved run to meet a gentle pass.','Add a passive defender controlling the line; discuss timing with your coach.','The passer is looking down and under pressure. Should you make the same run immediately?','Offer support or delay. A run works best when the passer can use it.','Describe one run you timed to the passer.'],
 ['pocket','Find a pocket between opponents','Team play','receive','Be available without hiding.','An attacking midfielder can receive in a gap, but the passing lane and pressure matter as much as the space.','Move a few steps to see the passer around the defender.','Standing in space that the ball cannot reach.','Place two cones as opponents. Move between gaps and check whether a wall pass can reach you.','Your brother serves while you move out from behind a cone into a visible lane; receive and return.','Add a walking defender; choose a new angle as they move.','You are between opponents but directly behind one from the passer’s view. Are you available?','Not yet. Adjust sideways to open a clear lane before calling for it.','Spot a small movement that made you available.'],
 ['reset','Keep it to attack again','Team play','switching','A backward pass can move the attack forward.','When the forward route closes, retaining the ball gives teammates time to find a better route.','Check for safe support before forcing the next action.','Treating every backward pass as failure.','Use three target gates: forward, side and back. Rehearse choosing the clear route with controlled passes.','Your brother blocks the forward gate. Protect, play back, and move to offer a new angle.','Use a third player to create two real supporting options.','The forward pass is covered and a teammate is free behind. What preserves the attack?','Use the safe support pass, then move again. Reassess rather than forcing the blocked lane.','Name one reset that helped your team keep possession.']
];
for(const [id,title,category,video,hook,why,cue,mistake,solo,duo,pressure,scenario,answer,evidence] of additions){const l={id,title,category,video:[video],why,cues:[cue],mistake,solo,duo,pressure,scenario,answer,evidence,nine:'Use the nearest teammate and clear space; follow your coach’s team shape.',eleven:'Check the nearby line and cover before moving; follow your coach’s team shape.',prereq:['scan','pass']};lessons.push(l);lessonById[id]=l}
// Normalize demonstration URLs for the guided reader as well as workout cards.
Object.values(demoCatalog).forEach(d=>{if(!d.url&&d.yt)d.url='https://www.youtube.com/watch?v='+d.yt});
let exerciseIndex=0,sessionKey='',sessionClock=null,clockRemaining=60,clockDeadline=0,clockKind='rest';
data.trainingSessions=data.trainingSessions||{};
function clearSessionClock(){clearInterval(sessionClock);sessionClock=null}
function appShell(page){clearSessionClock();pause();hub.hidden=false;document.body.classList.add('hub-mode');document.body.classList.remove('lesson-mode','workout-active');hubPage=page;nav.innerHTML=[['Today','Train'],['Learn','Learn'],['Progress','Progress']].map(([id,label])=>`<button data-hub="${id}" ${id===page?'aria-current="page"':''}>${label}</button>`).join('');hub.innerHTML=`<div class="quiet-top"><span class="quiet-brand">GALAXY / TRAINING</span><select id="appPlayer" aria-label="Player">${data.names.map((n,i)=>`<option value="${i}" ${i===player?'selected':''}>${escapeHTML(n)}</option>`).join('')}</select></div>`;$('appPlayer').onchange=e=>{player=Number(e.target.value);showHub(page)}}
const previousProgress=showHub;
showHub=function(page='Today'){
 if(page==='Progress'){appShell(page);const rows=Object.entries(data.journey.logs).filter(([k])=>k.startsWith(player+'|')).sort().reverse();hub.insertAdjacentHTML('beforeend','<h1>Your training.</h1><p>'+new Set([...rows.filter(([,r])=>r.kind!=='Pause').map(([k])=>k.split('|')[1]),...Object.entries(data.trainingSessions).filter(([k,r])=>k.startsWith(player+'|')&&r.completed.length===5).map(([k])=>k.split('|')[1])]).size+' active days recorded</p><p class="quiet-meta">No assigned weekdays. Your records stay in this browser.</p>'+rows.map(([k,r])=>'<article class="panel"><small>'+escapeHTML(k.split('|')[1])+' · '+escapeHTML(r.kind)+'</small><h3>'+escapeHTML(r.focus||'Recovery')+'</h3><p>'+escapeHTML(r.tried||'')+'</p><p>'+escapeHTML(r.note||'')+'</p></article>').join('')+strengthHistory()+'<button data-old="history">Earlier training records</button>');return}
 appShell(page);
 if(page==='Today')hub.insertAdjacentHTML('beforeend',`<h1>What’s your focus?</h1><p class="quiet-meta">Choose a session that fits today.</p><button class="session-choice" data-start><small>GAME INTELLIGENCE</small><h2>${escapeHTML(lessonById[prefs().focus].title)}</h2><span>Learn →</span></button><button class="session-choice" data-ball-session><small>ON THE BALL</small><h2>Ball Training</h2><p>Control, see, connect</p><span>3 drills · solo or with your brother →</span></button><button class="session-choice" data-lift-session="A"><small>STRENGTH</small><h2>Strength A</h2><p>Control & stability</p><span>5 exercises · one at a time →</span></button><button class="session-choice" data-lift-session="B"><small>STRENGTH</small><h2>Strength B</h2><p>Balance & body control</p><span>5 exercises · one at a time →</span></button><details class="quiet-extra"><summary>Log practice or a game</summary><button data-log="Practice">Practice</button> <button data-log="Game">Game</button></details><details class="quiet-extra"><summary>Parent setup & records</summary><p>Keep strength sessions on separate days. Skip added lifting when tired, unwell or close to a match. Both players have soccer experience; lifting still needs qualified technique instruction.</p><button data-old="strength">Exercise settings & full backup</button><button data-parent>Recovery settings</button></details>`);
 else{hub.insertAdjacentHTML('beforeend',`<h1>Read the game.</h1><p class="quiet-meta">${lessons.length} lessons · choose a problem to solve</p>`);[...new Set(lessons.map(l=>l.category))].forEach(c=>hub.insertAdjacentHTML('beforeend',`<details class="quiet-collection"><summary>${escapeHTML(c)} <span>${lessons.filter(l=>l.category===c).length}</span></summary>${lessons.filter(l=>l.category===c).map(l=>`<button class="quiet-lesson" data-focus="${l.id}">${escapeHTML(l.title)} →</button>`).join('')}</details>`))}
 window.scrollTo(0,0);
};
function strengthHistory(){return '<h2>Strength sessions</h2>'+Object.entries(data.trainingSessions).filter(([k])=>k.startsWith(player+'|')).sort().reverse().map(([k,r])=>{const parts=k.split('|');return '<article class="panel"><small>'+escapeHTML(parts[1])+'</small><h3>Strength '+escapeHTML(parts[2])+'</h3><p>'+r.completed.length+' of 5 exercises · '+(r.completed.length===5?'Complete':'In progress')+'</p></article>'}).join('')}
function demoLink(id){const d=demoCatalog[id];return d?`<a href="${d.url}" target="_blank" rel="noopener">▶ Watch ${escapeHTML(d.title)}</a>`:''}
function liftSession(){clearSessionClock();clockRemaining=60;clockKind='rest';document.body.classList.add('lesson-mode');const e=workouts[day][exerciseIndex],r=data.trainingSessions[sessionKey]||(data.trainingSessions[sessionKey]={completed:[]});hub.innerHTML=`<button data-hub="Today">← Sessions</button><p class="quiet-label">${exerciseIndex+1} OF ${workouts[day].length} · STRENGTH ${day}</p><h1>${e[0]}</h1><div class="rep-display">${e[1]} <small>${e[4]==='hold'?'seconds':'reps'}${e[2]?' each side':''}</small></div><p>${e[4]==='hold'?'Stand tall with one light dumbbell at your side. Do not lean. Hold once per side; rest between sides.':e[3]}</p><p class="quiet-meta">Start with one controlled set. ${e[4]==='hold'?'One hold per side in this technique session.':'Rest before moving on.'} Use your own comfortable load; no automatic increases.</p>${demoLink(strengthDemos[day][exerciseIndex+1][0])}<details class="quiet-extra"><summary>Why & what good looks like</summary><p>${whyExercise[e[0]][0]}</p><p>${whyExercise[e[0]][1]}</p></details><div class="session-timer"><strong id="sessionSeconds">60</strong><span id="sessionTimerLabel"> seconds · rest</span><div class="row"><button data-run-clock="60">Start rest</button>${e[4]==='hold'?'<button data-run-clock="15">Start hold</button>':''}<button data-pause-clock>Pause</button><button data-resume-clock>Resume</button></div></div><div class="row"><button data-lift-back ${exerciseIndex===0?'disabled':''}>Back</button><button class="primary" data-lift-next>${r.completed.includes(exerciseIndex)?'Completed · continue':exerciseIndex===4?'Complete session':'Complete & next'}</button></div>`;window.scrollTo(0,0)}
function ballSession(){document.body.classList.add('lesson-mode');hub.innerHTML=`<button data-hub="Today">← Sessions</button><h1>Control, see, connect.</h1><p>Use this instead of extra conditioning. On practice or game days, choose just one short drill if fresh.</p>${['touch','scan','pass'].map((id,i)=>{const l=lessonById[id];return `<details class="quiet-collection" ${i===0?'open':''}><summary>${i+1}. ${l.title}</summary><p><strong>Why:</strong> ${l.why}</p><p><strong>Solo:</strong> ${l.solo}</p><p><strong>Brother:</strong> ${l.duo}</p><p>Try five controlled attempts each, pause to discuss, then repeat once if fresh. Quality before speed.</p>${demoLink(l.video[0])}<details><summary>Add a decision</summary><p>${l.pressure}</p></details></details>`}).join('')}<button data-log="Home session" class="primary">Finish & reflect</button>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.liftSession){day=d.liftSession;sessionKey=player+'|'+localDate()+'|'+day;const prior=data.trainingSessions[sessionKey];exerciseIndex=prior?workouts[day].findIndex((_,i)=>!prior.completed.includes(i)):0;if(exerciseIndex<0){showHub('Progress');return}hub.innerHTML=`<button data-hub="Today">← Sessions</button><h1>Get ready.</h1><p>Warm up with easy movement, then rehearse each exercise without weight. Use a stable surface and clear space.</p><p>New to lifting? Have a qualified adult teach and check your form. Soccer experience does not replace lifting instruction.</p><p>Skip this session if sore, unwell or a match is close. Stop for pain.</p><button class="primary" data-lift-ready>Ready · begin</button>`;document.body.classList.add('lesson-mode')}
 if(d.liftReady!==undefined)liftSession();if(d.liftBack!==undefined&&exerciseIndex>0){exerciseIndex--;liftSession()}if(d.liftNext!==undefined){const r=data.trainingSessions[sessionKey];if(!r.completed.includes(exerciseIndex))r.completed.push(exerciseIndex);persist();if(exerciseIndex<4){exerciseIndex++;liftSession()}else{r.completedAt=new Date().toISOString();persist();clearSessionClock();hub.innerHTML='<h1>Session complete.</h1><p>Finish with easy walking. Keep one technique cue for next time.</p><button class="primary" data-log="Home session">Save reflection</button><button data-hub="Today">Back to sessions</button>'}}
 if(d.runClock||d.resumeClock!==undefined){clearSessionClock();if(d.runClock){clockRemaining=Number(d.runClock);clockKind=clockRemaining===15?'hold':'rest'}clockDeadline=Date.now()+clockRemaining*1000;const update=()=>{clockRemaining=Math.max(0,Math.ceil((clockDeadline-Date.now())/1000));$('sessionSeconds').textContent=clockRemaining;$('sessionTimerLabel').textContent=clockRemaining?' seconds · '+clockKind:' · complete';if(!clockRemaining)clearSessionClock()};update();if(clockRemaining)sessionClock=setInterval(update,250)}if(d.pauseClock!==undefined){if(sessionClock)clockRemaining=Math.max(0,Math.ceil((clockDeadline-Date.now())/1000));clearSessionClock()}if(d.ballSession!==undefined)ballSession();if(d.log)clearSessionClock();});
showHub('Today');
